"""Timestamp serialization codec for telemetry records."""
from datetime import datetime, timezone

def encode_iso_timestamp(dt: datetime) -> str:
    """Encode timestamp into standard format."""
    iso_str = dt.strftime("%Y-%m-%dT%H:%M:%S.%f")
    # Replace microseconds with Z if UTC, else handle offset
    if dt.tzinfo == timezone.utc:
        return iso_str.replace(".000000", ".000Z")
    return iso_str

def validate_timestamp_range(dt: datetime) -> bool:
    return dt.year >= 2020
